using System;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.IO;
class NormalizeAssets {static void Main(string[] a){string[] names={"sit","relax","sleep"};double[] mw={278,394,285},mh={316,249,239};for(int i=0;i<3;i++)using(Bitmap src=new Bitmap(Path.Combine(a[0],names[i]+".png")))using(Bitmap dst=new Bitmap(840,720,PixelFormat.Format32bppArgb)){dst.SetResolution(96,96);double f=Math.Min(mw[i]/src.Width,mh[i]/src.Height);float w=(float)(src.Width*f*2),h=(float)(src.Height*f*2);using(Graphics g=Graphics.FromImage(dst)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.DrawImage(src,new RectangleF((840-w)/2,720-h-24,w,h));}dst.Save(Path.Combine(a[1],names[i]+".png"),ImageFormat.Png);Console.WriteLine(names[i]+" packed into 840x720");}}}
